import sys

MOD = 998244353

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.parity = [0] * n
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            orig = self.parent[x]
            self.parent[x] = self.find(orig)
            self.parity[x] ^= self.parity[orig]
        return self.parent[x]

    def union(self, x, y, c):
        # We want: parity(x) XOR parity(y) = c
        rx = self.find(x)
        ry = self.find(y)
        px = self.parity[x]
        py = self.parity[y]
        if rx == ry:
            return (px ^ py) == c
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
            self.parity[rx] = px ^ py ^ c
        else:
            self.parent[ry] = rx
            self.parity[ry] = px ^ py ^ c
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1
        return True

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        H = int(next(it)); W = int(next(it))
        grid = [list(next(it).strip()) for _ in range(H)]

        row_A = [0] * H
        col_A = [0] * W
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 'A':
                    row_A[i] += 1
                    col_A[j] += 1

        valid = True
        all_A_row = [False] * H
        for i in range(H):
            if row_A[i] == W:
                all_A_row[i] = True
                if W % 2 == 1:
                    valid = False
                    break
            else:
                if row_A[i] % 2 == 1:
                    valid = False
                    break
        if not valid:
            out_lines.append("0")
            continue

        for j in range(W):
            if col_A[j] % 2 == 1:
                valid = False
                break
        if not valid:
            out_lines.append("0")
            continue

        k = sum(all_A_row)

        mixed_ids = []
        mixed_id_map = [-1] * H
        for i in range(H):
            if not all_A_row[i]:
                mixed_id_map[i] = len(mixed_ids)
                mixed_ids.append(i)
        M = len(mixed_ids)

        if M == 0:
            ans = pow(2, k, MOD) * pow(2, W, MOD) % MOD
            out_lines.append(str(ans))
            continue

        col_B_rows = [[] for _ in range(W)]
        u_list = [None] * M
        current_prefix = [0] * W

        for i in range(H):
            if not all_A_row[i]:
                id = mixed_id_map[i]
                v = [0] * W
                a_count = 0
                for j in range(W):
                    if grid[i][j] == 'A':
                        v[j] = 0
                        a_count += 1
                    else:  # 'B'
                        if a_count % 2 == 0:
                            v[j] = 1
                        else:
                            v[j] = 0
                u = [v[j] ^ current_prefix[j] for j in range(W)]
                u_list[id] = u
                for j in range(W):
                    if grid[i][j] == 'B':
                        col_B_rows[j].append(id)
            # Update current_prefix
            for j in range(W):
                current_prefix[j] ^= (1 if grid[i][j] == 'A' else 0)

        dsu = DSU(M)
        F = [True] * W
        for j in range(W):
            rows = col_B_rows[j]
            if not rows:
                continue
            F[j] = False
            ref = rows[0]
            for i in rows[1:]:
                c = u_list[i][j] ^ u_list[ref][j]
                if not dsu.union(i, ref, c):
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            out_lines.append("0")
            continue

        # Count connected components
        roots = set()
        for i in range(M):
            roots.add(dsu.find(i))
        C = len(roots)

        F_count = sum(F)
        ans = pow(2, k, MOD) * pow(2, C, MOD) % MOD
        ans = ans * pow(2, F_count, MOD) % MOD
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

