import sys
sys.setrecursionlimit(1 << 25)

def solve():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    # Prefix distinct counts
    pref = [0] * N
    seen = [0] * (N + 1)
    cnt = 0
    for i in range(N):
        if seen[A[i]] == 0:
            cnt += 1
            seen[A[i]] = 1
        pref[i] = cnt

    # Suffix distinct counts
    suffix = [0] * (N + 1)
    seen = [0] * (N + 1)
    cnt = 0
    for i in range(N - 1, -1, -1):
        if seen[A[i]] == 0:
            cnt += 1
            seen[A[i]] = 1
        suffix[i] = cnt
    # suffix[N] remains 0

    # Segment tree for range add and range max
    size = 1
    while size < N:
        size <<= 1
    tree = [0] * (2 * size)
    lazy = [0] * (2 * size)

    def apply(node, val):
        tree[node] += val
        lazy[node] += val

    def push(node):
        if lazy[node] != 0:
            apply(node * 2, lazy[node])
            apply(node * 2 + 1, lazy[node])
            lazy[node] = 0

    def add(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            apply(node, val)
            return
        push(node)
        mid = (l + r) // 2
        if ql <= mid:
            add(node * 2, l, mid, ql, qr, val)
        if qr > mid:
            add(node * 2 + 1, mid + 1, r, ql, qr, val)
        tree[node] = max(tree[node * 2], tree[node * 2 + 1])

    def query(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree[node]
        push(node)
        mid = (l + r) // 2
        res = -10**9
        if ql <= mid:
            res = max(res, query(node * 2, l, mid, ql, qr))
        if qr > mid:
            res = max(res, query(node * 2 + 1, mid + 1, r, ql, qr))
        return res

    last_occ = {}
    ans = 0

    for j in range(N):
        v = A[j]
        if v in last_occ:
            p = last_occ[v]
            # Add 1 to range [p, j-1] (C_j(i) for i in this range increases by 1)
            if p <= j - 1:
                add(1, 0, size - 1, p, j - 1, 1)
        last_occ[v] = j

        # Only consider splits where middle ends at j (1 <= j <= N-2)
        if 1 <= j <= N - 2:
            max_c = query(1, 0, size - 1, 0, j - 1)
            total = pref[j] + max_c + suffix[j + 1]
            if total > ans:
                ans = total

    print(ans)

if __name__ == "__main__":
    solve()

