import sys
from collections import defaultdict

MOD = 998244353

def solve():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N-1)]

    # Factorize all A_i
    maxA = max(A) if A else 0
    spf = list(range(maxA+1))
    for i in range(2, int(maxA**0.5)+1):
        if spf[i] == i:
            step = i
            start = i*i
            for j in range(start, maxA+1, step):
                if spf[j] == j:
                    spf[j] = i

    def factor(x):
        fac = {}
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            fac[p] = cnt
        return fac

    # Collect all primes and their exponent lists
    prime_exps = {}  # prime -> list of exponents of length N-1
    for i, a in enumerate(A):
        fac = factor(a)
        for p, e in fac.items():
            if p not in prime_exps:
                prime_exps[p] = [0]*(N-1)
            prime_exps[p][i] = e

    # Also, we need to consider primes that might have e1=0 but appear in other A_i. Already included.
    # Now, for each prime, compute the sum contribution.
    total = 1
    for p, e_list in prime_exps.items():
        e = e_list  # length N-1
        # Precompute powers of p and inverse
        inv_p = pow(p, MOD-2, MOD)
        # Function to compute p^k mod MOD, k can be negative
        def powp(k):
            if k >= 0:
                return pow(p, k, MOD)
            else:
                return pow(inv_p, -k, MOD)
        # DP: state = (a, ci, m, l) -> value = sum of p^{sum B} mod MOD
        # a: A_i (exponent of p in d_i)
        # ci: c_i (binary choice for orientation at edge i)
        # m: min B_j so far
        # l: max (-A_j) for j=1..i-1
        # We start at i=1, choose c1, compute B1, etc.
        dp = defaultdict(int)
        # Initialize for i=1
        # Choose c1: if e1>0, both 0 and 1; if e1=0, only 0
        if e[0] == 0:
            c1_choices = [0]
        else:
            c1_choices = [0, 1]
        for c1 in c1_choices:
            a = 0  # A1=0
            ci = c1
            B1 = e[0] * (1 - c1)
            m = B1
            l = 0  # no previous A
            val = powp(B1)
            dp[(a, ci, m, l)] = (dp[(a, ci, m, l)] + val) % MOD

        # Process transitions from i to i+1, for i=1 to N-2
        for i in range(1, N-1):
            dp_next = defaultdict(int)
            # e_i and e_{i+1}
            ei = e[i-1]  # since e[0] is e1
            ei1 = e[i]
            # Choices for c_{i+1}
            if ei1 == 0:
                ci1_choices = [0]
            else:
                ci1_choices = [0, 1]
            for (a, ci, m, l), val in dp.items():
                for ci1 in ci1_choices:
                    new_a = a + ei * ci - ei1 * (1 - ci1)
                    new_B = a + ei * ci  # B_{i+1}
                    new_m = min(m, new_B)
                    new_l = max(l, -new_a)
                    new_val = val * powp(new_B) % MOD
                    state = (new_a, ci1, new_m, new_l)
                    dp_next[state] = (dp_next[state] + new_val) % MOD
            dp = dp_next

        # After loop, we have states for i = N-1
        # Now we need to add B_N for each state and then evaluate
        # B_N = A_{N-1} + e_{N-1} * c_{N-1}
        # e_{N-1} is e[N-2]
        eN1 = e[N-2]
        contribution = 0
        # Precompute p^{-N}
        inv_pN = pow(inv_p, N, MOD)
        for (a, ci, m, l), val in dp.items():
            BN = a + eN1 * ci
            new_m = min(m, BN)
            new_val = val * powp(BN) % MOD
            if -new_m >= l:
                # contribution = new_val * (p^{-N})^{new_m}
                contrib = new_val * pow(inv_pN, new_m, MOD) % MOD
                contribution = (contribution + contrib) % MOD
        total = total * contribution % MOD

    print(total)

