class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        total = 0

        # Single digit non-zero substrings
        for i in range(n):
            if s[i] != '0':
                total += 1

        # Multi-digit substrings, need length >= 2
        for i in range(n):
            if s[i] == '0':
                continue
            num = 0
            for j in range(i + 1, n):
                num = num * 10 + int(s[j - 1])
                if s[j] == '0':
                    continue
                if num % int(s[j]) == 0:
                    total += 1

        return total

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        # For each subarray length from 1 to k
        for length in range(1, k + 1):
            # Use monotonic deques for min and max
            min_deque = []  # stores indices, values in increasing order
            max_deque = []  # stores indices, values in decreasing order

            for i in range(n):
                # Add nums[i] to the window
                # For min deque: remove from back while last element >= current
                while min_deque and nums[min_deque[-1]] >= nums[i]:
                    min_deque.pop()
                min_deque.append(i)

                # For max deque: remove from back while last element <= current
                while max_deque and nums[max_deque[-1]] <= nums[i]:
                    max_deque.pop()
                max_deque.append(i)

                # Remove elements outside the window
                if min_deque[0] <= i - length:
                    min_deque.pop(0)
                if max_deque[0] <= i - length:
                    max_deque.pop(0)

                # If window is full (i >= length - 1), add contribution
                if i >= length - 1:
                    min_val = nums[min_deque[0]]
                    max_val = nums[max_deque[0]]
                    total += min_val + max_val

        return total

