    import sys
    input = sys.stdin.readline
    N = int(input().strip())
    buildings = []
    for _ in range(N):
        x, h = map(int, input().split())
        buildings.append((x, h))

    max_t = -float('inf')
    for i in range(N - 1):
        x1, h1 = buildings[i]
        x2, h2 = buildings[i + 1]
        # T_i is the height where b_i = b_{i+1}
        # b_i = (H_i - h) / X_i
        # b_{i+1} = (H_{i+1} - h) / X_{i+1}
        # Setting equal: (H_i - h)/X_i = (H_{i+1} - h)/X_{i+1}
        # Solving for h: h = (H_{i+1} * X_i - H_i * X_{i+1}) / (X_i - X_{i+1})
        num = h2 * x1 - h1 * x2
        den = x1 - x2  # negative since x1 < x2
        t = num / den
        if t > max_t:
            max_t = t

    if max_t < 0:
        print(-1)
    else:
        # Print with sufficient precision
        print("{:.18f}".format(max_t))

