class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1

        # Function to compute the minimum cost for a given k
        def compute_cost(k):
            # dp[carry] = min cost after processing some characters with given carry (surplus to pass right)
            INF = 10**9
            dp = [INF] * (n + 1)
            dp[0] = 0

            for i in range(26):
                fi = cnt[i]
                if k == 0:
                    # Special case: demand is 0 for all, so we can just delete everything at this node or send to right
                    # But for k=0, we know the optimal is to delete all, so we can return n
                    # However, we still need to handle the DP for consistency
                    pass

                # For demand = 0
                # g0[c] = dp[c] + fi + c  (since |fi + c - 0| = fi + c)
                g0 = [INF] * (n + 1)
                for c in range(n + 1):
                    if dp[c] < INF:
                        g0[c] = dp[c] + fi + c

                # Compute suffix min of g0
                suff0 = [INF] * (n + 1)
                cur = INF
                for c in range(n, -1, -1):
                    if g0[c] < cur:
                        cur = g0[c]
                    suff0[c] = cur

                # For demand = k
                g1 = [INF] * (n + 1)
                for c in range(n + 1):
                    if dp[c] < INF:
                        avail = fi + c
                        if avail >= k:
                            g1[c] = dp[c] + (avail - k)
                        else:
                            g1[c] = dp[c] + (k - avail)

                # Compute suffix min of g1
                suff1 = [INF] * (n + 1)
                cur = INF
                for c in range(n, -1, -1):
                    if g1[c] < cur:
                        cur = g1[c]
                    suff1[c] = cur

                new_dp = [INF] * (n + 1)
                for s in range(n + 1):
                    # From demand = 0
                    idx0 = s - fi
                    if idx0 < 0:
                        idx0 = 0
                    v0 = suff0[idx0]
                    if v0 < new_dp[s]:
                        new_dp[s] = v0

                    # From demand = k
                    if s == 0:
                        # Any c can reach s=0
                        v1 = suff1[0]
                        if v1 < new_dp[s]:
                            new_dp[s] = v1
                    else:
                        idx1 = s + k - fi
                        if idx1 < 0:
                            idx1 = 0
                        v1 = suff1[idx1]
                        if v1 < new_dp[s]:
                            new_dp[s] = v1

                dp = new_dp

            # Add final deletion cost for any carry
            ans = INF
            for c in range(n + 1):
                if dp[c] < INF:
                    total = dp[c] + c  # delete the remaining carry
                    if total < ans:
                        ans = total
            return ans

        # k=0 is a special case: delete all characters
        best = n  # cost to delete all

        # Try k from 1 to n
        # Since the function is convex, we can use ternary search
        lo, hi = 1, n
        # To handle small n, we can just try all k
        if n <= 2000:
            for k in range(1, n + 1):
                c = compute_cost(k)
                if c < best:
                    best = c
        else:
            # Ternary search for minimum
            while hi - lo > 3:
                m1 = lo + (hi - lo) // 3
                m2 = hi - (hi - lo) // 3
                c1 = compute_cost(m1)
                c2 = compute_cost(m2)
                if c1 < c2:
                    hi = m2
                else:
                    lo = m1
            for k in range(lo, hi + 1):
                c = compute_cost(k)
                if c < best:
                    best = c

        return best
